import{_ as t,o as a,c as n,a2 as d}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"OpenClaw","description":"在 OpenClaw 中添加 Tokeness 模型提供商，配置 OpenAI Compatible、Base URL、API Key 和模型名。","frontmatter":{"title":"OpenClaw","description":"在 OpenClaw 中添加 Tokeness 模型提供商，配置 OpenAI Compatible、Base URL、API Key 和模型名。"},"headers":[],"relativePath":"integrations/openclaw.md","filePath":"integrations/openclaw.md","lastUpdated":1782306957000}'),s={name:"integrations/openclaw.md"};function o(l,e,i,p,r,h){return a(),n("div",null,[...e[0]||(e[0]=[d(`<h1 id="openclaw" tabindex="-1">OpenClaw <a class="header-anchor" href="#openclaw" aria-label="Permalink to &quot;OpenClaw&quot;">​</a></h1><p>OpenClaw 支持添加模型提供商。接入 Tokeness 时，按 OpenAI Compatible 供应商配置即可。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>API Type</td><td><code>OpenAI Compatible</code> 或 <code>OpenAI</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model</td><td>从 Tokeness 模型广场复制</td></tr></tbody></table><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先在 Tokeness 控制台完成：</p><ol><li>确认余额可用。</li><li>创建 OpenClaw 专用 API Key。</li><li>复制要使用的模型名。</li><li>打开使用日志页面。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openclaw-local</span></span></code></pre></div><h2 id="_2-打开-openclaw-模型设置" tabindex="-1">2. 打开 OpenClaw 模型设置 <a class="header-anchor" href="#_2-打开-openclaw-模型设置" aria-label="Permalink to &quot;2. 打开 OpenClaw 模型设置&quot;">​</a></h2><p>进入 OpenClaw 管理页面，找到模型、Config、Models、Provider 或 Model Provider 相关设置。不同版本的入口名称可能不同，但需要添加的是“模型提供商”。</p><p>如果 OpenClaw 提供初始化向导，也可以在向导中选择自定义模型供应商。</p><h2 id="_3-添加-tokeness-provider" tabindex="-1">3. 添加 Tokeness Provider <a class="header-anchor" href="#_3-添加-tokeness-provider" aria-label="Permalink to &quot;3. 添加 Tokeness Provider&quot;">​</a></h2><p>新建一个 Provider：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Name: Tokeness</span></span>
<span class="line"><span>API Type: OpenAI Compatible</span></span>
<span class="line"><span>Base URL: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: 你的 Tokeness API Key</span></span>
<span class="line"><span>Model: 从 Tokeness 模型广场复制的模型名</span></span></code></pre></div><p>如果 OpenClaw 区分 Chat Model、Reasoning Model、Small Model，可以先全部填写同一个已验证可用的模型。确认跑通后，再按任务类型拆分。</p><p>如果 OpenClaw 支持从 <code>/v1/models</code> 获取模型列表，可以尝试自动拉取。失败时手动填写模型名。</p><h2 id="_4-保存并启用" tabindex="-1">4. 保存并启用 <a class="header-anchor" href="#_4-保存并启用" aria-label="Permalink to &quot;4. 保存并启用&quot;">​</a></h2><p>保存 Provider 后，确认当前 Agent 或默认模型已经切到 Tokeness。</p><p>需要检查两处：</p><ol><li>Provider 已保存。</li><li>当前 Agent 实际使用的模型配置已选择 Tokeness。</li></ol><p>有些工具保存 Provider 后不会自动切换默认模型，需要再到 Agent 配置里选一次。</p><h2 id="_5-验证" tabindex="-1">5. 验证 <a class="header-anchor" href="#_5-验证" aria-label="Permalink to &quot;5. 验证&quot;">​</a></h2><p>在 OpenClaw 中发起一个短任务：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只回复一句话，说明当前 OpenClaw 已经接入 Tokeness。</span></span></code></pre></div><p>然后打开 Tokeness 使用日志：</p><ul><li>有新请求，说明请求已进入 Tokeness。</li><li>模型名正确，说明配置生效。</li><li>状态码成功，说明 Key、余额和模型权限正常。</li></ul><h2 id="_6-多模型配置" tabindex="-1">6. 多模型配置 <a class="header-anchor" href="#_6-多模型配置" aria-label="Permalink to &quot;6. 多模型配置&quot;">​</a></h2><p>OpenClaw 常见场景可以拆成多套模型：</p><table tabindex="0"><thead><tr><th>配置</th><th>用途</th></tr></thead><tbody><tr><td>Main Model</td><td>主要对话、任务规划</td></tr><tr><td>Coding Model</td><td>代码修改、项目分析</td></tr><tr><td>Fast Model</td><td>简单回复、标题、摘要</td></tr><tr><td>Reasoning Model</td><td>复杂推理、长任务</td></tr></tbody></table><p>每个模型都可以使用同一个 Tokeness Base URL，只需要模型名不同。</p><h2 id="_7-key-与额度" tabindex="-1">7. Key 与额度 <a class="header-anchor" href="#_7-key-与额度" aria-label="Permalink to &quot;7. Key 与额度&quot;">​</a></h2><p>OpenClaw 常用于长任务和自动化操作，适合单独设置 Key 和额度。</p><p>Key 管理可以按下面方式处理：</p><ul><li>给 OpenClaw 单独建 Key。</li><li>第一次接入先设置较小额度。</li><li>跑长任务前确认模型价格。</li><li>定期看使用日志，确认是否有异常重试。</li><li>不要把 OpenClaw 配置目录上传到公开仓库。</li></ul><h2 id="_8-排查" tabindex="-1">8. 排查 <a class="header-anchor" href="#_8-排查" aria-label="Permalink to &quot;8. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>401 Unauthorized</td><td>API Key 错误、禁用或复制时带了空格</td></tr><tr><td>403 Forbidden</td><td>Key 分组、额度、模型权限或账户状态异常</td></tr><tr><td>404 Not Found</td><td>Base URL 应填写 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>从模型广场重新复制模型名</td></tr><tr><td>保存后仍走旧模型</td><td>Provider 保存后，还要在 Agent 默认模型里切换</td></tr><tr><td>Tokeness 无日志</td><td>OpenClaw 当前 Agent 没有使用 Tokeness Provider</td></tr><tr><td>自动拉模型失败</td><td>手动填写模型名</td></tr><tr><td>长任务中断</td><td>检查模型上下文、工具调用、余额和超时设置</td></tr></tbody></table>`,37)])])}const k=t(s,[["render",o]]);export{b as __pageData,k as default};
